def compute(vars):
    commercial_tdrs = vars["v1"]
    total_tdrs = vars["v2"]

    if total_tdrs == 0:
        return None

    value = (commercial_tdrs / total_tdrs) * 100
    return {
        "value": value,
        "trace": {
            "commercial_tdrs": commercial_tdrs,
            "total_tdrs": total_tdrs,
            "ratio": commercial_tdrs / total_tdrs,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
